const EXPECTED_TOKEN = 'REPLACE_WITH_ADVANCE_INTERNAL_TOKEN';
const headers = $input.first().json.headers || {};
const token = headers['x-advance-token'];
if (token !== EXPECTED_TOKEN) {
  return [];
}
const b = $input.first().json.body || {};
const esc = (s) => { if (s === undefined || s === null || s === '') return '\u2014'; return String(s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])); };
// 2026-09-21 sweep: a Graph subject is plain text, so build it with txt(), not the HTML esc()
// (esc gave 'Blues &amp; Brews' and a bare dash for a blank event name). esc stays for the HTML body.
const txt = (s) => (s === undefined || s === null) ? '' : String(s).replace(/\s+/g, ' ').trim();
let subject, rows, to;
if (b.event_type === 'booking') {
  { const a = txt(b.artist_name), ev = txt(b.event_name), v = txt(b.venue);
    // event segment only when set and not a copy of the artist (3rd-party bookings with no band)
    subject = 'New booking: ' + (a || '(no artist)') + ((ev && ev.toLowerCase() !== a.toLowerCase()) ? ' \u2014 ' + ev : '') + (v ? ' @ ' + v : ''); }
  rows = [
    ['Event', b.event_name], ['Date', b.event_date], ['Venue', b.venue],
    ['Artist', b.artist_name], ['Set start', b.event_start], ['Set length', b.set_time],
    ['Contact email', b.contact_email], ['Entered by', b.entered_by],
  ];
  to = 'blloyd@3cdc.org,Jmayborg@3cdc.org';
} else {
  { const bn = txt(b.band_name), v = txt(b.venue);
    subject = 'Advance form completed: ' + (bn || '(no band name)') + (v ? ' @ ' + v : ''); }
  rows = [
    ['Band', b.band_name], ['Venue', b.venue], ['Show date', b.show_date],
    ['Contact', [b.contact_name, b.contact_phone].filter(Boolean).join(' \u2014 ')],
    ['Performers + crew', b.performers], ['Monitors', b.monitors],
    ['Own engineer', b.own_engineer],
    ['Stage plot', b.stage_plot_carried_from ? ('Carried from ' + b.stage_plot_carried_from)
                   : (b.stage_plot_file ? 'Uploaded' : (b.stage_plot_desc || '\u2014'))],
    ['Vehicles', (b.vehicle_count !== undefined && b.vehicle_count !== '')
                 ? (b.vehicle_count + ' total' + ((b.large_vehicle_count !== undefined && b.large_vehicle_count !== '') ? ', ' + b.large_vehicle_count + ' large' : ''))
                 : ''],
    ['Stage escort', [b.stage_escort_name, b.stage_escort_cell].filter(Boolean).join(' \u2014 ')],
  ];
  // Brian, 2026-09-11: the band-completed-form notify goes to him AND the
  // shared Production inbox now — the new-booking notify stays Brian-only.
  to = 'blloyd@3cdc.org,production@3cdc.org';
}
const tr = rows.filter(r => r[1] !== undefined && r[1] !== null && r[1] !== '')
  .map(r => `<tr><td style="padding:4px 10px 4px 0;color:#6b7280;font:13px -apple-system,sans-serif">${r[0]}</td><td style="padding:4px 0;font:13px -apple-system,sans-serif"><b>${esc(r[1])}</b></td></tr>`).join('');
// Brian, 2026-09-14: a completed form links straight to the band's own page, not the search page
const aid = (b._db && b._db.artist_id) ? b._db.artist_id : null;
const link = aid ? `https://advance.tinydoorstudios.com/artist/${aid}` : 'https://advance.tinydoorstudios.com/search';
const linkText = aid ? `Open ${esc(b.band_name)}'s page \u2192` : 'Open the advance search \u2192';
const html = `<div style="font-family:-apple-system,sans-serif"><table>${tr}</table><p style="margin-top:14px"><a href="${link}">${linkText}</a></p></div>`;
return [{ json: { subject, html, to } }];
